-- 1. How much revenue is generated by each hour of the day?
SELECT
    EXTRACT(HOUR FROM e.event_time) AS purchase_hour,
    SUM(e.price) AS total_revenue
FROM events AS e
WHERE e.event_type = 'purchase'
GROUP BY purchase_hour
ORDER BY purchase_hour;

-- 2. How much revenue is generated by each weekday?
SELECT
    EXTRACT(DOW FROM e.event_time) AS day_of_week_number,
    TRIM(TO_CHAR(e.event_time, 'Day')) AS day_of_week_name,
    SUM(e.price) AS total_revenue
FROM events AS e
WHERE e.event_type = 'purchase'
GROUP BY
    day_of_week_number,
    day_of_week_name
ORDER BY day_of_week_number;

-- 3. Which hour is the peak shopping hour based on total events?
SELECT
    EXTRACT(HOUR FROM e.event_time) AS event_hour,
    COUNT(*) AS total_events,
    COUNT(DISTINCT e.user_id) AS unique_customers,
    COUNT(DISTINCT e.user_session) AS unique_sessions
FROM events AS e
GROUP BY event_hour
ORDER BY total_events DESC
LIMIT 1;

-- 4. Which day is the peak shopping day based on total events?
SELECT
    e.event_date,
    COUNT(*) AS total_events,
    COUNT(DISTINCT e.user_id) AS unique_customers,
    COUNT(DISTINCT e.user_session) AS unique_sessions
FROM events AS e
GROUP BY e.event_date
ORDER BY total_events DESC
LIMIT 1;

-- 5. How many purchases occur by each hour of the day?
SELECT
    EXTRACT(HOUR FROM e.event_time) AS purchase_hour,
    COUNT(*) AS purchase_count
FROM events AS e
WHERE e.event_type = 'purchase'
GROUP BY purchase_hour
ORDER BY purchase_hour;
